using RealmForge.Domain.Entities;
using RealmForge.Shared.Enums;

namespace RealmForge.Infrastructure.Persistence.Seeding.ClassesData;

///	<summary>
///	Wild Magic Sorcery (sorcerer, 2024 ruleset). Not in the SRD: names and mechanics as in the rules, with descriptions written for RealmForge in English and Italian.
///	</summary>
public static class WildMagicSorcery2024Seeder
{
	public static readonly Guid SubclassId = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "subclass", "wild-magic-sorcery");

	public static Subclass Build()
	{
		return new Subclass
		{
			Id = SubclassId,
			CharacterClassId = Sorcerer2024Seeder.ClassId,
			Ruleset = RulesetVersion.Dnd5e_2024,
			IsOfficialSRD = true,
			Source = ContentSource.RealmForge,
			CasterProgression = CasterProgression.None,
			SpellcastingAbility = null,
			Translations = new List<SubclassTranslation>
			{
				new SubclassTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "subclass", "wild-magic-sorcery", "en"), Language = LanguageCode.En, Name = "Wild Magic Sorcery", Description = "Your innate magic rises from the forces of chaos that lie beneath the order of creation. You or an ancestor may have been exposed to raw magic, perhaps through a planar gate opening onto Limbo or the Elemental Planes; you may have been blessed by a fey creature or branded by a demon; or your power may be a fluke with no clear cause. Whatever its source, this magic seethes inside you, waiting for any way out." },
				new SubclassTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "subclass", "wild-magic-sorcery", "it"), Language = LanguageCode.It, Name = "Stregoneria della Magia Selvaggia", Description = "La magia innata dello stregone nasce dalle forze del caos che si celano sotto l'ordine del creato. Lui o un suo antenato potrebbe essere stato esposto alla magia grezza, forse attraverso un portale planare affacciato sul Limbo o sui Piani Elementali; forse è stato benedetto da un folletto o marchiato da un demone; oppure il suo potere è un caso fortuito senza una causa evidente. Qualunque sia la sua origine, questa magia ribolle dentro di lui, in attesa di trovare uno sfogo." }
			},
			Features = new List<ClassFeature>
			{
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/wild-magic-surge"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 3,
					SortOrder = 0,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/wild-magic-surge", "en"), Language = LanguageCode.En, Name = "Wild Magic Surge", Description = "Your spells can release bursts of untamed magic. Once per turn, right after you cast a Sorcerer spell with a spell slot, you can roll 1d20; on a 20, roll on the Wild Magic Surge table (see Tamed Surge) to produce a magical effect.\n\nIf that effect is a spell, it is too unstable for your Metamagic to alter." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/wild-magic-surge", "it"), Language = LanguageCode.It, Name = "Impulso di Magia Selvaggia", Description = "Gli incantesimi dello stregone possono scatenare impulsi di magia incontrollata. Una volta per turno, subito dopo aver lanciato un incantesimo da stregone con uno slot incantesimo, può tirare 1d20: con un 20, tira sulla tabella Impulsi di magia selvaggia (vedi Impulsi Domati) per generare un effetto magico.\n\nSe l'effetto magico è un incantesimo, è troppo instabile per essere modificato dalla Metamagia." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/tides-of-chaos"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 3,
					SortOrder = 1,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/tides-of-chaos", "en"), Language = LanguageCode.En, Name = "Tides of Chaos", Description = "Chaos answers your call. Before rolling the d20 for a D20 Test, you can grant that roll Advantage. This feature then stays spent until you either finish a Long Rest or spend a spell slot on a Sorcerer spell, and that spell triggers an automatic roll on the Wild Magic Surge table if it comes before the Long Rest." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/tides-of-chaos", "it"), Language = LanguageCode.It, Name = "Onde di Caos", Description = "Lo stregone può manipolare il caos stesso per conferirsi vantaggio a una prova del d20 prima di tirare il dado. Dopo averlo fatto, deve lanciare un incantesimo da stregone con uno slot incantesimo o completare un riposo lungo prima di poter usare di nuovo questo privilegio.\n\nSe lancia un incantesimo da stregone con uno slot incantesimo prima di aver completato un riposo lungo, tira automaticamente sulla tabella Impulsi di magia selvaggia." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/bend-luck"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 6,
					SortOrder = 2,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/bend-luck", "en"), Language = LanguageCode.En, Name = "Bend Luck", Description = "Your wild magic lets you twist fate. Right after another creature you can see rolls the d20 for a D20 Test, you can use your Reaction and spend 1 Sorcery Point to roll 1d4, applying the result as a bonus or a penalty (your choice) to that d20 roll." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/bend-luck", "it"), Language = LanguageCode.It, Name = "Piegare la Fortuna", Description = "Lo stregone sa distorcere il destino con la sua magia selvaggia. Subito dopo che un'altra creatura che è in grado di vedere ha tirato il d20 per una prova del d20, può usare una reazione e spendere 1 punto stregoneria per tirare 1d4 e applicarne il risultato come bonus o penalità (a sua scelta) al tiro del d20." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/controlled-chaos"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 14,
					SortOrder = 3,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/controlled-chaos", "en"), Language = LanguageCode.En, Name = "Controlled Chaos", Description = "You gain a measure of control over your surges: each time you roll on the Wild Magic Surge table, you can roll twice and pick either result." },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/controlled-chaos", "it"), Language = LanguageCode.It, Name = "Caos Controllato", Description = "Lo stregone acquisisce un minimo di controllo sugli impulsi della sua magia selvaggia: ogni volta che tira sulla tabella Impulsi di magia selvaggia, può tirare due volte e usare il risultato che preferisce." }
					}
				},
				new ClassFeature
				{
					Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/tamed-surge"),
					Ruleset = RulesetVersion.Dnd5e_2024,
					Level = 18,
					SortOrder = 4,
					Translations = new List<ClassFeatureTranslation>
					{
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/tamed-surge", "en"), Language = LanguageCode.En, Name = "Tamed Surge", Description = "Right after you cast a Sorcerer spell with a spell slot, you can pick an effect of your choice from the Wild Magic Surge table rather than rolling on it. Any effect except the last row is allowed, and if the chosen effect calls for a roll, you must make it.\n\nYou can use this feature once per Long Rest.\n\n**Wild Magic Surge**\n\n| 1d100 | Effect |\n|---|---|\n| 01–04 | For the next minute, roll on this table at the start of each of your turns, ignoring this result on later rolls. |\n| 05–08 | A creature Friendly to you appears in a random unoccupied space within 60 feet of you; the DM controls it, and it vanishes after 1 minute. Roll 1d4: 1 a modron duodrone, 2 a flumph, 3 a modron monodrone, 4 a unicorn (stat blocks are in the Monster Manual). |\n| 09–12 | For the next minute, you regain 5 Hit Points at the start of each of your turns. |\n| 13–16 | Creatures have Disadvantage on saving throws against the next spell you cast within the next minute that calls for a save. |\n| 17–20 | You undergo an effect lasting 1 minute unless stated otherwise. Roll 1d8: 1 faint, otherworldly music surrounds you, heard only by you and creatures within 5 feet; 2 your size grows by one category; 3 you sprout a long beard of feathers that stays until you sneeze, when the feathers burst from your face and vanish; 4 you must shout whenever you speak; 5 illusory butterflies flit through the air within 10 feet of you; 6 an eye opens on your forehead, giving you Advantage on Wisdom (Perception) checks; 7 pink bubbles float from your mouth whenever you speak; 8 your skin turns bright blue for 24 hours or until a *Remove Curse* spell ends the effect. |\n| 21–24 | For the next minute, every spell of yours with a casting time of an action has a casting time of a Bonus Action instead. |\n| 25–28 | You are whisked to the Astral Plane until the end of your next turn, then return to the space you left or, if it is occupied, the nearest unoccupied space. |\n| 29–32 | The next time you cast a damaging spell within the next minute, don't roll its damage dice; use the maximum on each one instead. |\n| 33–36 | For the next minute, you have Resistance to all damage. |\n| 37–40 | You become a potted plant until the start of your next turn. As a plant you are Incapacitated and have Vulnerability to all damage; if you drop to 0 Hit Points, the pot shatters and you return to your normal form. |\n| 41–44 | For the next minute, you can teleport up to 20 feet as a Bonus Action on each of your turns. |\n| 45–48 | You and up to three creatures of your choice within 30 feet of you become Invisible for 1 minute. A creature's invisibility ends right after it makes an attack roll, deals damage, or casts a spell. |\n| 49–52 | For the next minute, a ghostly shield floats beside you, granting a +2 bonus to AC and immunity to *Magic Missile*. |\n| 53–56 | You can take one additional action this turn. |\n| 57–60 | You cast a random spell; if it normally requires Concentration, this time it doesn't and lasts its full duration. Roll 1d10: 1 *Confusion*; 2 *Fireball*; 3 *Fog Cloud*; 4 *Fly* on a random creature within 60 feet; 5 *Grease*; 6 *Levitate* on yourself; 7 *Magic Missile* cast as a level 5 spell; 8 *Mirror Image*; 9 *Polymorph* on yourself (if you fail the save, you become a goat); 10 *See Invisibility*. |\n| 61–64 | For the next minute, any flammable, nonmagical object you touch that no other creature is wearing or carrying catches fire, takes 1d4 Fire damage, and keeps burning. |\n| 65–68 | If you die within the next hour, you instantly return to life as if by the *Reincarnate* spell. |\n| 69–72 | You are Frightened until the end of your next turn; the DM decides what you fear. |\n| 73–76 | You teleport up to 60 feet to an unoccupied space you can see. |\n| 77–80 | A random creature within 60 feet of you is Poisoned for 1d4 hours. |\n| 81–84 | For the next minute, you shed Bright Light in a 30-foot radius; any creature ending its turn within 5 feet of you is Blinded until the end of its next turn. |\n| 85–88 | Up to three creatures of your choice that you can see within 30 feet of you take 1d10 Necrotic damage, and you regain Hit Points equal to the total Necrotic damage dealt. |\n| 89–92 | Up to three creatures of your choice that you can see within 30 feet of you take 4d10 Lightning damage. |\n| 93–96 | For the next minute, you and every creature within 30 feet of you have Vulnerability to Piercing damage. |\n| 97–00 | Roll 1d6: 1 you regain 2d10 Hit Points; 2 an ally of your choice within 300 feet regains 2d10 Hit Points; 3 you regain your lowest-level expended spell slot; 4 an ally of your choice within 300 feet regains their lowest-level expended spell slot; 5 you regain all your expended Sorcery Points; 6 every effect of row 17–20 affects you at once. |" },
						new ClassFeatureTranslation { Id = DeterministicGuid.ForSrd(RulesetVersion.Dnd5e_2024, "class-feature", "wild-magic-sorcery/tamed-surge", "it"), Language = LanguageCode.It, Name = "Impulsi Domati", Description = "Subito dopo aver lanciato un incantesimo da stregone con uno slot incantesimo, lo stregone può generare un effetto a sua scelta dalla tabella Impulsi di magia selvaggia anziché tirare su di essa. Può scegliere qualsiasi effetto tranne quello dell'ultima riga e, se l'effetto scelto richiede un tiro, deve effettuarlo.\n\nDopo aver usato questo privilegio, non può farlo di nuovo finché non completa un riposo lungo.\n\n**Impulsi di magia selvaggia**\n\n| 1d100 | Effetto |\n|---|---|\n| 01–04 | Per il minuto successivo, all'inizio di ognuno dei suoi turni lo stregone tira su questa tabella, ignorando questo risultato nei tiri successivi. |\n| 05–08 | In uno spazio libero casuale entro 18 metri dallo stregone compare una creatura amichevole nei suoi confronti, controllata dal DM, che scompare dopo 1 minuto. Tira 1d4: 1 un duodrone modron, 2 un flumph, 3 un monodrone modron, 4 un unicorno (le statistiche si trovano nel manuale dei mostri). |\n| 09–12 | Per il minuto successivo, lo stregone recupera 5 punti ferita all'inizio di ognuno dei suoi turni. |\n| 13–16 | Le creature subiscono svantaggio ai tiri salvezza contro il prossimo incantesimo con tiro salvezza che lo stregone lancia entro il minuto successivo. |\n| 17–20 | Lo stregone subisce un effetto che dura 1 minuto, salvo diversa indicazione. Tira 1d8: 1 una musica eterea e lieve lo circonda, udibile solo da lui e dalle creature entro 1,5 metri; 2 la sua taglia aumenta di una categoria; 3 gli cresce una lunga barba di piume che resta finché non starnutisce, quando le piume esplodono dal suo viso e svaniscono; 4 deve gridare quando parla; 5 farfalle illusorie svolazzano nell'aria entro 3 metri da lui; 6 gli compare un occhio sulla fronte che gli conferisce vantaggio alle prove di Saggezza (Percezione); 7 bolle rosa gli escono dalla bocca quando parla; 8 la sua pelle diventa di un blu acceso per 24 ore o finché l'effetto non viene rimosso da un incantesimo *rimuovi maledizione*. |\n| 21–24 | Per il minuto successivo, tutti gli incantesimi dello stregone con un tempo di lancio di un'azione hanno invece un tempo di lancio di un'azione bonus. |\n| 25–28 | Lo stregone viene trasportato sul Piano Astrale fino alla fine del suo turno successivo, poi torna nello spazio che occupava o, se è occupato, nello spazio libero più vicino. |\n| 29–32 | La prossima volta che, entro il minuto successivo, lancia un incantesimo che infligge danni, lo stregone non tira i dadi dei danni: usa per ciascuno il valore massimo. |\n| 33–36 | Per il minuto successivo, lo stregone ha resistenza a tutti i danni. |\n| 37–40 | Lo stregone si trasforma in una pianta in vaso fino all'inizio del suo turno successivo. Come pianta è incapacitato e ha vulnerabilità a tutti i danni; se scende a 0 punti ferita, il vaso si rompe e lo stregone riprende la sua forma. |\n| 41–44 | Per il minuto successivo, in ognuno dei suoi turni lo stregone può teletrasportarsi fino a 6 metri come azione bonus. |\n| 45–48 | Lo stregone e fino a tre creature a sua scelta entro 9 metri da lui diventano invisibili per 1 minuto. L'invisibilità di una creatura termina subito dopo che effettua un tiro per colpire, infligge danni o lancia un incantesimo. |\n| 49–52 | Per il minuto successivo, uno scudo spettrale fluttua accanto allo stregone, conferendogli un bonus di +2 alla CA e l'immunità all'incantesimo *dardo incantato*. |\n| 53–56 | Lo stregone può effettuare un'azione aggiuntiva in questo turno. |\n| 57–60 | Lo stregone lancia un incantesimo casuale; se normalmente richiede concentrazione, in questo caso non la richiede e dura per tutta la sua durata. Tira 1d10: 1 *confusione*; 2 *palla di fuoco*; 3 *nube di nebbia*; 4 *volare* su una creatura casuale entro 18 metri; 5 *unto*; 6 *levitazione* su se stesso; 7 *dardo incantato* lanciato come incantesimo di 5° livello; 8 *immagine speculare*; 9 *metamorfosi* su se stesso (se fallisce il tiro salvezza, diventa una capra); 10 *vedere invisibilità*. |\n| 61–64 | Per il minuto successivo, ogni oggetto infiammabile e non magico che lo stregone tocca, e che non è indossato o trasportato da un'altra creatura, prende fuoco, subisce 1d4 danni da fuoco e continua a bruciare. |\n| 65–68 | Se lo stregone muore entro l'ora successiva, torna subito in vita come per l'incantesimo *reincarnazione*. |\n| 69–72 | Lo stregone è spaventato fino alla fine del suo turno successivo; è il DM a stabilire la fonte della sua paura. |\n| 73–76 | Lo stregone si teletrasporta fino a 18 metri in uno spazio libero che è in grado di vedere. |\n| 77–80 | Una creatura casuale entro 18 metri dallo stregone subisce la condizione di avvelenato per 1d4 ore. |\n| 81–84 | Per il minuto successivo, lo stregone emana luce intensa in un raggio di 9 metri; ogni creatura che termina il turno entro 1,5 metri da lui è accecata fino alla fine del suo turno successivo. |\n| 85–88 | Fino a tre creature a scelta dello stregone che è in grado di vedere entro 9 metri da lui subiscono 1d10 danni necrotici; lo stregone recupera punti ferita pari alla somma dei danni necrotici inflitti. |\n| 89–92 | Fino a tre creature a scelta dello stregone che è in grado di vedere entro 9 metri da lui subiscono 4d10 danni da fulmine. |\n| 93–96 | Per il minuto successivo, lo stregone e tutte le creature entro 9 metri da lui hanno vulnerabilità ai danni perforanti. |\n| 97–00 | Tira 1d6: 1 lo stregone recupera 2d10 punti ferita; 2 un alleato a sua scelta entro 90 metri recupera 2d10 punti ferita; 3 lo stregone recupera il suo slot incantesimo speso di livello più basso; 4 un alleato a sua scelta entro 90 metri recupera il suo slot incantesimo speso di livello più basso; 5 lo stregone recupera tutti i punti stregoneria spesi; 6 tutti gli effetti della riga 17–20 lo colpiscono contemporaneamente. |" }
					}
				}
			}
		};
	}
}
